theorem.raw:
\label{thm: main, intro} Let   $\pi $ be as above. There exists $\sigma$ as above such that for any $z \in {\mathbb {C}} \smallsetminus \{0\}$ we have
		\begin{align}\label{0eq: Bessel identity}
		i_{\hskip 0.5 pt \pi, \hskip 0.5 pt \psi_1} \begin{pmatrix}
		z / 4 & 1 \\ 1 &
		\end{pmatrix}
		= \frac {2 \epsilon (\pi, 1/2) \, \psi_1     \lp   2 / z \rp |z|} {L(\pi, 1/2)}  j_{\sigma, \hskip 0.5 pt \psi_1} \begin{pmatrix}
		& - z\- \\ z \\
		\end{pmatrix},
		\end{align}
		in which $L (\pi, 1/2)$ and  $\epsilon (\pi, 1/2)$ are the central values of the $L$-factor and the $\epsilon$-factor associated with $ \pi $.

\label{thm: W(g) on BwB}
		Let $\varv \in H_{\infty}$. Then
		\begin{align}
		W_{\varv} \lp
		g \rp
		=  \int_{\BCx } j \big( g t \big( a\- \big) \big)  W_{\varv} \lp
		t (a)
		\rp \dx  a,
		\end{align}
		for all $ g  \in B \varw_0 B$.

\label{thm: main}
	For each irreducible   unitary representation $\pi$ of $G / Z$, there exists a corresponding irreducible   unitary representation $\sigma $ of $S$ satisfying the Bessel identity \eqref{eq: Bessel indentity}. The correspondence is given by
	\begin{align*}
	\pi_{\mu, \shskip m}  \longrightarrow \sigma_{\frac 1 2 \mu, \shskip \frac 1 2 m}, \hskip 10 pt \text{for } \mu \in i \shskip {\mathbb {R}}, m \text{ even, or } \mu \in \big( 0, \tfrac 1 2\big) \hskip -1 pt , m = 0.
	\end{align*}

Assume that $f$ and $f '$ satisfy \eqref{eq: O AN = O NN} and that $\pi$ and $\sigma$ correspond as in Theorem {\rm\ref{thm: main}}. Then
\begin{equation}
I_{\pi,\shskip \psi} (f) = J_{\sigma,\shskip \psi^D} (f') \epsilon (\pi, 1/2, \psi)    / \|2 D\| L (\pi, 1/2).
\end{equation}

lemma.raw:
\label{4lem: bounds for J}
		Suppose that $|{\mathrm{Re}\,} \mu | < \rho$. We have
		\begin{equation*}
		\bfJ_{ \mu,\shskip   m} \lp z \rp \lll \left\{\begin{split}
		& 1 / \left| z  \right|^{2 \rho}, \hskip 11 pt \text{ if } |z| \leqslant 1, \\
		& 1 /{\textstyle \sqrt {|z|}}, \hskip 10 pt \text{ if } |z| > 1,
		\end{split}\right.
		\end{equation*}
		with the implied constant depending only on $\mu$, $\rho$ and $m$. In particular,
		\begin{equation*}
		\bfJ_{ \mu,\shskip   m} \lp z \rp \lll   1 / \left| z  \right|^{2 \rho} + 1 / {\textstyle \sqrt {|z|}}.
		\end{equation*}

\label{6lem: rel Bessel for split f}
		Let $f \in C_c^{\infty} (X)$ be of the form
		\begin{align}\label{6eq: f splits}
		f (t(a) z(c) n(x) \varw_0 n(y)) = f_1 (a) f_2 (c) f_3 (x) f_4 (y),
		\end{align}
		with $f_1,  f_2 \in  C_c^{\infty}  (\BCx)$ and $f_3, f_4 \in C_c^{\infty}  ({\mathbb {C}})$. Then
		\begin{equation}\label{6eq: double int for I}
		\begin{split}
		& \int_{\BCx}    \int_{G}  f(t(b)g) j  (g) dg \shskip   \dx  b \\
		 = \ & \int_{\BCx} f_1 (b) \dx  b \int_{\BCx} f_2 (c) \dx  c  \int_{{\mathbb {C}}}   f_4 (y ) \psi (y) d y \int_{\BCx} j  (t(a) \varw_0) \widehat f_3 (a) \dx  a,
		\end{split}
		\end{equation}
		where $ \widehat f_2 $ is the $\psi$-Fourier transform of $f_2$   defined as in  \eqref{def: Fourier}.

proof.raw:
The proof is literally the same as that of \cite[Lemma 2.1]{BaruchMao-Real}. We have
	\begin{align*}
	\int_{\BCx} f(a)W_{\pi(n(x))\varv}(t(a))\dx  a  = \hskip -1 pt \int_{\BCx} f(a)W_{ \varv}(t(a) n(x))\dx  a  = \hskip -1 pt \int_{\BCx} f(a)W_{ \varv}(t(a) ) \psi (ax) \dx  a.
	\end{align*}
	Hence follows the integrability of the first integral for all $x \in {\mathbb {C}}$ and it is equal to the Fourier transform of the function $\|a\|\- f(a)W_{ \varv}(t(a) ) $. The identity in the lemma then yields the equality between the Fourier transform of $\|a\|\- f(a)W_{ \varv}(t(a) ) $ and that of $\|a\|\- g (a)W_{ \varv}(t(a) ) $. It follows that $f(a)W_\varv(t(a))=g(a)W_\varv(t(a))$ for all $a\in \BCx$.

We have
\begin{align*}
& \hskip 13 pt  \int  \widetilde J (\rho_r(t(a)) f)W_{\varv}(t(a))\dx  a \\
&= \int \left(\int_{X}f(gt(a))j (g)dg\right) W_\varv(t(a)) \dx  a \\
&= \int \left( \int_{X}f(g)j (gt(a^{-1}))dg \right)  W_\varv(t(a))\dx  a  \\
&= \int_{X} f(g) \left( \int  j (gt(a^{-1}))W_\varv(t(a))\dx  a \right)dg  \\
&= \int_{X} f(g)W_\varv(g)dg.
\end{align*}
Here we have obtained the last equality from \eqref{thm: W(g) on BwB} in Theorem \ref{thm: W(g) on BwB}. It is however needed to justify the change of order of integrations in the second to the last equality. For this, it suffices to verify the absolute convergence of the integral in the third line. Note that
\begin{align*}
&\int_{X}|f(g)j (gt(a^{-1}))|dg \\
= \ &\int |j (t(ab)\varw_0)|\left(\iiint |f(n(x)z(c)t(b)\varw_0n(y))|dxdy\dx  c \right) |b|^{-2}\dx  b \\
= \ & \int |j (t(ab)\varw_0)| \lp  \int  J \big( \sqrt b,   c, |f| \big)    \dx  c  \rp |b|^{-2} \dx  b,
\end{align*}
where $ J \big( \sqrt b,   c, |f| \big) $ is the orbital integral defined as in \eqref{def: J (a,c,f)}.  In view of Proposition \ref{prop:A1}, the inner integral over $c$ is  dominated by  $  |b|^{1 + \varepsilon} \Upsilon_B (b)$ for some    constant $B$, with $\Upsilon_B$ the characteristic function on $\{ b: |b| \geqslant B \}$. Since $\pi = \pi_{\mu, \shskip  m}$ is unitary, we have   $|{\mathrm{Re}\,} \mu | <   \frac 1 2$. In view of  Lemma \ref{4lem: bounds for J} and the expression of $j = j_{\pi, \shskip \psi}$ as in \eqref{4eq : j = J}, $j   (t(a) \varw_0)$ is bounded by $1 +   {|a|}^{\frac 1 2}$. Consequently, we have the following estimations for the integral above
\begin{align*}
\lll \int   \big(  1 +   {|ab|}^{\frac 1 2} \big) |b|^{- 3 + \varepsilon} \Upsilon_B (b) d b \lll 1 + |a|^{\frac 1 2}.
\end{align*}
Finally, recall from Lemma \ref{lem: asymptotic of W(t(a))} that $W_{\varv} (t(a))$ is rapidly decreasing at infinity and of the order $|a|^{2\rho}$ near zero for certain $\rho > 0$, then follows the absolute convergence of the integral.

Fix $h\in C_c^\infty(S)$. Let  $U \subset Z$ be a small open neighborhood of the identity  $1$ so that the map $ (s, z) \rightarrow s z $ is an injection from $S \times U$ into $G = S \cdot Z$. 
   Choose a function $\tw \in C_c^{\infty} (U)$ with
   \begin{align*}
  \int_{U} \tw(z) d  z = 1,
   \end{align*}
   where $d z = \dx  c$ if $z = z(c)$.

   Set $f (s z) = h (s) \omega_{\pi}\- (z) \tw (z) $.






Clearly, $f$ is well defined and $f \in C_c^{\infty} (G)$ (indeed, $f \in C_c^{\infty} (S \cdot U)$).
   By Corollary \ref{cor53}, along with the  $(\omega_{\pi}, Z)$-equivariance of $j_{\pi, \shskip \psi}$ (see \eqref{4eq: psi variant}), we have
   \begin{align*}
    J_{\pi,\shskip \psi}(  f)&=\int_G  f(g) j_{\pi,\shskip \psi}(g) dg  =    \int_{U} \tw(z)d  z \int_Sh(s) j_{\pi,\shskip \psi}(s)ds     = \int_S h(s) j_{\pi,\shskip \psi}(s)ds.
   \end{align*}
   On the other hand, since $\sigma$ is the restriction of $\pi$ to $S$,    we may prove  in a similar fashion that $\pi (f) \varv = \sigma (h) \varv$ for any $\varv \in H$. Precisely,
   \begin{align*}
   \int_G f(g)\pi(g)\varv \,  dg   = \int_{U } \tw(z)d  z \int_S h(s) \pi(s)\varv \,  ds
   =  \int_S h(s) \sigma (s)\varv \,  ds.
   \end{align*}
   In view of the definitions in \S \ref{sec: distributions}, it   follows that $\varv_{L, \shskip f}=\varv_{L,\shskip h}$ and that $J_{\pi,\shskip \psi}(f)=J_{\sigma,\shskip \psi}(h)$. The proof is now completed.

Let $dg = \dx  a  \hskip 1 pt  \dx c \hskip 1 pt  d x \hskip 1 pt  d y$ be a Haar measure on $X$ for $g = t(a)  z(c) n(x) \varw_0 n(y)$. In view of \eqref{4eq: psi variant} and \eqref{6eq: f splits},
	the integral on the left hand side of \eqref{6eq: double int for I}   splits into the product
	\begin{align*}
	& \int  f_2 (c) \dx  c  \int   f_4 (y ) \psi (y) d y \int  \lp  \int  f_1 (ab) j  (t(a) \varw_0) \int f_3 (x) \psi (  a x) d x \shskip  \dx  a \rp \dx  b \\
	= \ & \int  f_2 (c) \dx  c  \int   f_4 (y ) \psi (y) d y \iint        f_1 (ab) j  (t(a) \varw_0) \widehat f_3 (a)    \dx  a \shskip   \dx  b.
	\end{align*}
	We claim that the last double integral converges absolutely. Hence we may change the order of integrations and the variable $b$ to $b/a$, getting
	\begin{align*}
	\iint        f_1 (ab) j  (t(a) \varw_0) \widehat f_3 (a)    \dx  a \shskip   \dx  b & = \int         j  (t(a) \varw_0) \widehat f_3 (a)  \int f_1 (ab) \dx  b \shskip   \dx  a \\
	& = \int f_1 (b  ) \dx  b \int    j  (t(a) \varw_0) \widehat f_3 (a)     \dx  a.
	\end{align*}
	We now show   the absolute  convergence. Choose $|{\mathrm{Re}\,} \mu | < \rho <  \frac 1 2$.  Lemma \ref{4lem: bounds for J} implies that $j  (t(a) \varw_0)$ may be bounded by $|a|^{1 - 2\rho} +   {|a|}^{\frac 1 2}$. We can find positive constants $A$ and $B$ such that $f_1 (a ) \lll \Upsilon_{A, B} (a)$, with $ \Upsilon_{A, B} (a)$ defined to be the characteristic function on the annulus $\left\{ a : A \leqslant |a| \leqslant B \right\}$. Hence
	\begin{align*}
	\int      \big|  f_1 (ab) j  (t(a) \varw_0) \widehat f_3(a)  \big|  \dx  a  \lll \int \Upsilon_{A/|b|, B/|b|} (a) \big|\widehat f_3 (a) \big| \big( |a|^{- 1- 2 \rho} + |a|^{- \frac 3 2} \big) d a.
	\end{align*}
	Since $\widehat f_3 (a)$ is rapidly decreasing when $|a|$ is large, it follows that the value of the integral above is rapidly decreasing when $|b|$ is small. When $|b|$ is large the integral is bounded by $  |b|^{2 \rho - 1} + |b|^{- \frac 1 2}$. It is then clear that integrating further with $\dx  b = d b / |b|^2$ will converge absolutely  at both $0$ and $\infty$.

