    We extend the definition of $j $ to the whole group $G$ by setting $j (g)=0$ for $g\notin X $.
\begin{prop}\label{thm: local integrability}
		Assume that $\pi $ is unitary. Then $j $ is locally integrable over $G$. Namely, for any $f\in C_c^\infty(G)$, we have
\[
\int_G \left|f(g)j (g) \right| dg<\infty.
\]
	\end{prop}
\begin{proof} Recall that the measure on $X = NA \varw_0 N$ is given by $ d g = |a|^{-2} d x \hskip 1 pt \dx  a   \hskip 1 pt \dx c \hskip 1 pt d y$ if $g = n(x)z(c)t(a)\varw_0n(y)$. We have
\begin{align*}
 \int_G |f(g)j (g)| dg
= \ & \int_{X}|f(g)j (g)|dg \\
= \ &\int |j (t(a)\varw_0)|\left(\iiint |f(n(x)z(c)t(a)\varw_0n(y))|dxdy\dx  c \right) |a|^{-2}\dx  a \\
= \ & \int |j (t(a)\varw_0)| \lp  \int  J \big( \sqrt a,   c, |f| \big)    \dx  c  \rp |a|^{-2} \dx  a,
\end{align*}
where $ J \big( \sqrt a,   c, |f| \big) $ is the orbital integral defined as in \eqref{def: J (a,c,f)}.  In view of Proposition \ref{prop:A1},  the inner integral over $c$ is zero for small $|a|$    and of the order $|a|^{1+\varepsilon}$ for large  $|a|$. In view of  Lemma \ref{4lem: bounds for J} and the expression of $j = j_{\pi, \shskip \psi}$ as in \eqref{4eq : j = J}, $j   (t(a) \varw_0)$ is bounded by $ {|a|}^{\frac 1 2}$ when $|a|$ is large. It is now clear that the integral above is convergent.
\end{proof}



	\section {Bessel distributions for ${\mathrm {GL}}_2({\mathbb {C}})$}

	In this section, we show that the Bessel distribution
	$J=J_{\pi,\shskip \psi}$ 
	  is represented by the Bessel function $j=j_{\pi,\shskip \psi}$. 

	\begin{lem}{\label{le41}}
		Let $\varv\in H_\infty$, then
		\[
		\int_{\BCx}J(\rho_r(t(a))f)W_{\varv}(t(a))\dx a=\int_Gf(g)W_{\varv}(g)dg,
		\]
		in which $\rho_r$ is the right translation, that is, $(\rho_r (h) f)(g) = f (  g h)$.
	\end{lem}
   \begin{proof}The proof is similar to that of   \cite[Lemma 7.1]{BaruchMao-Real}.
   For any $\varv\in H_\infty$, we have
   \begin{align*}
    \pi(\rho_r(t(a))f) \varv 
    & =    \int_G f(gt(a))\pi(g) \varv \shskip dg \\
    & =\int_G f(g)\pi(g)\pi(t(a^{-1})) \varv\shskip dg = \pi (f) \pi(t(a^{-1})) \varv.
   \end{align*}
   Thus it follow from  \eqref{def: vector v l f}, \eqref{def: J (f)} and \eqref{def: Wv(g)} that $\varv_{L,\hskip 1 pt \rho_r(t(a))f}=\pi(t(a))\varv_{L, \shskip f}$ and $J (\rho_r(t(a))f)=\overline {W_{\varv_{L, \shskip f}}(t(a))}$. Hence, in view of \eqref{eq: inner product}, we have
   \[
   \int_{\BCx} J (\rho_r(t(a))f)W_\varv(t(a))\dx  a=\langle \varv,\varv_{L, \shskip f} \rangle.
   \]
   On the other hand, by \eqref{def: vector v l f} and \eqref{def: Wv(g)},
   \[
   \langle \varv,\varv_{L, \shskip f} \rangle =L(\pi(f)\varv)=\int_G f(g)W_\varv(g)dg,
   \]
   which finishes the proof.
   \end{proof}
   Recall the definition of the Bessel function $ j = j_{\pi,\shskip \psi} $ in the last section. We define a distribution $\widetilde J = \widetilde J_{\pi,\shskip \psi}$ on $C_c^\infty(G)$ by
   \[
   \widetilde J (f)=\int_{G}f(g)j(g)dg.
   \]	
   This distribution is well defined as we have proven in Proposition \ref{thm: local integrability} that $j_{\pi,\shskip \psi}(g)$ is locally integrable on $G$.
\begin{lem}
{\label{le42}}\footnote{Lemma \ref{le42} is stronger than Lemma 7.2 in \cite{BaruchMao-Real}  as our computation shows that it is not necessary to assume that $W_{\varv} (t(a))$ has  a high order of vanishing at $a = 0$.} Let $\varv\in H_\infty$ and $f\in C_c^\infty(G)$. 
Then
\[
\int_{\BCx} \widetilde J (\rho_r(t(a)) f)W_{\varv}(t(a))\dx  a=\int_G f(g)W_{\varv}(g)dg.
\]
\end{lem}
\begin{proof} We have
\begin{align*}
& \hskip 13 pt  \int  \widetilde J (\rho_r(t(a)) f)W_{\varv}(t(a))\dx  a \\
&= \int \left(\int_{X}f(gt(a))j (g)dg\right) W_\varv(t(a)) \dx  a \\
&= \int \left( \int_{X}f(g)j (gt(a^{-1}))dg \right)  W_\varv(t(a))\dx  a  \\
&= \int_{X} f(g) \left( \int  j (gt(a^{-1}))W_\varv(t(a))\dx  a \right)dg  \\
&= \int_{X} f(g)W_\varv(g)dg.
\end{align*}
Here we have obtained the last equality from \eqref{thm: W(g) on BwB} in Theorem \ref{thm: W(g) on BwB}. It is however needed to justify the change of order of integrations in the second to the last equality. For this, it suffices to verify the absolute convergence of the integral in the third line. Note that
\begin{align*}
&\int_{X}|f(g)j (gt(a^{-1}))|dg \\
= \ &\int |j (t(ab)\varw_0)|\left(\iiint |f(n(x)z(c)t(b)\varw_0n(y))|dxdy\dx  c \right) |b|^{-2}\dx  b \\
= \ & \int |j (t(ab)\varw_0)| \lp  \int  J \big( \sqrt b,   c, |f| \big)    \dx  c  \rp |b|^{-2} \dx  b,
\end{align*}
where $ J \big( \sqrt b,   c, |f| \big) $ is the orbital integral defined as in \eqref{def: J (a,c,f)}.  In view of Proposition \ref{prop:A1}, the inner integral over $c$ is  dominated by  $  |b|^{1 + \varepsilon} \Upsilon_B (b)$ for some    constant $B$, with $\Upsilon_B$ the characteristic function on $\{ b: |b| \geqslant B \}$. Since $\pi = \pi_{\mu, \shskip  m}$ is unitary, we have   $|{\mathrm{Re}\,} \mu | <   \frac 1 2$. In view of  Lemma \ref{4lem: bounds for J} and the expression of $j = j_{\pi, \shskip \psi}$ as in \eqref{4eq : j = J}, $j   (t(a) \varw_0)$ is bounded by $1 +   {|a|}^{\frac 1 2}$. Consequently, we have the following estimations for the integral above
\begin{align*}
\lll \int   \big(  1 +   {|ab|}^{\frac 1 2} \big) |b|^{- 3 + \varepsilon} \Upsilon_B (b) d b \lll 1 + |a|^{\frac 1 2}.
\end{align*}
Finally, recall from Lemma \ref{lem: asymptotic of W(t(a))} that $W_{\varv} (t(a))$ is rapidly decreasing at infinity and of the order $|a|^{2\rho}$ near zero for certain $\rho > 0$, then follows the absolute convergence of the integral.
\end{proof}



    \begin{cor}{\label{cor53}}
		The two distributions $\widetilde J $ and $J $ are the same. That is, for any $f\in C_c^\infty(G)$, we have
\[
J (f)=\int_G f(g)j (g)dg.
\]
	\end{cor}
    \begin{proof}
    Choose $\varv\in H_\infty$ with $W_{\varv} (1) = 1$, say. 
    By Lemma \ref{le41} and   \ref{le42} we have
    \[
    \int  J (\rho_r(t(a))f)W_\varv(t(a))\dx  a=\int  \widetilde J (\rho_r(t(a))f)W_\varv(t(a))\dx  a
    \]
    for all $f\in C_c^\infty(G)$. We replace $\varv$ by $\pi(n)\varv$ for any  $n\in N$ and apply Lemma \ref{le21}, it follows that
    \[
    J (\rho_r(t(a))f)W_\varv(t(a))=\widetilde J (\rho_r(t(a))f)W_\varv(t(a))
    \]
    for all $a\in \BCx$. Letting $a = 1$, the conclusion follows immediately.
    \end{proof}

Let $\sigma=\sigma_{\mu, \shskip m}$ and $\pi=\pi_{\mu, \shskip m}$ be unitary principal series of $S$ and $G$ respectively; see \S \ref{sec: representations of G and S}. Recall that $\sigma $ is the restriction of $\pi$ on $S$. Let $H$   be their common underlying space. Let  $L$ be a fixed common $\psi$-Whittaker functional. Let  the  Bessel distribution $J_{\sigma,\shskip \psi}$  be defined by (\ref{def: v l phi, S}, \ref{def: J(phi), S}). We now prove that the  Bessel distribution $J_{\sigma,\shskip \psi}$  is represented by the restriction of the Bessel function $j_{\pi,\shskip \psi}$ to $S$.

    \begin{prop}\label{prop54: regularity of J on S}	
    Let $\sigma $ and $\pi$ be as above.  For any $h\in C_c^\infty(S)$, we have
    \[
    J_{\sigma,\shskip \psi}(h)=\int_S h(s) j_{\pi,\shskip \psi}(s) ds.
    \]
    As such, we shall write $j_{\sigma, \shskip \psi} $ the restriction of $j_{\pi,\shskip \psi}$ on $S$.
    \end{prop}
   \begin{proof} 
   Fix $h\in C_c^\infty(S)$. Let  $U \subset Z$ be a small open neighborhood of the identity  $1$ so that the map $ (s, z) \rightarrow s z $ is an injection from $S \times U$ into $G = S \cdot Z$. 
   Choose a function $\tw \in C_c^{\infty} (U)$ with
   \begin{align*}
  \int_{U} \tw(z) d  z = 1,
   \end{align*}
   where $d z = \dx  c$ if $z = z(c)$.

   Set $f (s z) = h (s) \omega_{\pi}\- (z) \tw (z) $.






Clearly, $f$ is well defined and $f \in C_c^{\infty} (G)$ (indeed, $f \in C_c^{\infty} (S \cdot U)$).
   By Corollary \ref{cor53}, along with the  $(\omega_{\pi}, Z)$-equivariance of $j_{\pi, \shskip \psi}$ (see \eqref{4eq: psi variant}), we have
   \begin{align*}
    J_{\pi,\shskip \psi}(  f)&=\int_G  f(g) j_{\pi,\shskip \psi}(g) dg  =    \int_{U} \tw(z)d  z \int_Sh(s) j_{\pi,\shskip \psi}(s)ds     = \int_S h(s) j_{\pi,\shskip \psi}(s)ds.
   \end{align*}
   On the other hand, since $\sigma$ is the restriction of $\pi$ to $S$,    we may prove  in a similar fashion that $\pi (f) \varv = \sigma (h) \varv$ for any $\varv \in H$. Precisely,
   \begin{align*}
   \int_G f(g)\pi(g)\varv \,  dg   = \int_{U } \tw(z)d  z \int_S h(s) \pi(s)\varv \,  ds
   =  \int_S h(s) \sigma (s)\varv \,  ds.
   \end{align*}
   In view of the definitions in \S \ref{sec: distributions}, it   follows that $\varv_{L, \shskip f}=\varv_{L,\shskip h}$ and that $J_{\pi,\shskip \psi}(f)=J_{\sigma,\shskip \psi}(h)$. The proof is now completed.
   \end{proof}

For $h \in C_c^{\infty} (S)$ we introduced the orbital integral
\begin{align}\label{eq: O NN (g)}
O^{N, \shskip N}_{h, \shskip \psi} (g) = \iint      h (n(x) g   n(y) ) \psi (x) \psi (y) d x d y.
\end{align}
This orbital integral was studied by Jacquet. In particular, it is proven in \cite{Jacquet-RTF}
that the integral in \eqref{eq: O NN (g)} converges absolutely for all $g \in  X \cap S = N (A\cap S) \varw N$. In view of Proposition \ref{prop54: regularity of J on S}, along with \eqref{4eq: psi variant, SL}, for $h \in C_c^{\infty} (S)$ we have
\begin{align}\label{eq: J = int O}
J_{\sigma,\shskip \psi} (h) = \int  O^{N, \shskip N}_{h, \shskip \psi} (s(a) \varw) j_{\sigma,\shskip \psi} (s(a) \varw) \|a\|^{-2} \dx  a.
\end{align}

A formula for the Fourier transform of Bessel functions
The Fourier transform $\widehat f  $ of a Schwartz  function $f$ on ${\mathbb {C}}$ is defined by
	\begin{equation*}
	\widehat f (u) = \sideset{ }{_{\mathbb {C}} }{\iint} \shskip  f (z) e(- {\mathrm{Tr}}  (uz) ) \shskip  i d z   \nwedge   d \overline z.
	\end{equation*}

According to \cite[Corollary 1.5]{Qi-II-G}, when $|{\mathrm{Re}\,} \mu | < \frac 1 2$ and $m$ is even, we have
	\begin{equation}\label{6eq: Fourier}
	\begin{split}
	\sideset{ }{_{{\mathbb {C}} } }{\iint}  \hskip - 2 pt   \bfJ_{\mu,\shskip  m} \lp z \rp    \widehat f (z)  \frac {i d z   \nwedge   d \overline z} {  {|z|}}   = \frac  1 2 \sideset{ }{_{{\mathbb {C}} } }{\iint}     e \lp {\mathrm{Tr}}  \lp \frac 1 {2 u} \rp \rp \hskip - 2 pt \bfJ_{\frac 1 2 \mu,\shskip  \frac 1 2 m} \lp  \frac 1  { 16 u ^{ 2} } \rp \hskip - 1 pt f (u) \frac {i d u  \nwedge  d \overline u} {  {|u|}},
	\end{split}
	\end{equation}
	if $f$ is a Schwartz function on ${\mathbb {C}}$. Note that there is abuse of the notation $d z$, as $d z$ in this article denotes $2 |\lambdaup|$ times of the Lebesgue measure on ${\mathbb {C}}$.

	It is critical that  the test function $f$ in \eqref{6eq: Fourier transform of j} only need to be Schwartz on ${\mathbb {C}}$ and rapid decay or vanishing at $0$ is not required. We also remark that the deduction from  \eqref{eq: main 1} to \eqref{6eq: Fourier} is   not so straightforward; see \cite[\S 6]{Qi-II-G} for more details.

	Recall from \eqref{def: Fourier} that the  Fourier transform with respect to the additive character $\psi (z) = \psi_{\lambdaup} (z) = e({\mathrm{Tr}}(\lambdaup z))$ is defined by
	\begin{align*}
	\widehat f (u) = \int_{ {\mathbb {C}}} f (z) \psi  (uz) d z.
	\end{align*}
	Thus, in view of \eqref{4eq : j = J}, 
	the identity \eqref{6eq: Fourier} may be rephrased as
	\begin{align} \label{6eq: Fourier transform of j}
	\sideset{ }{_{\BCx} }{\int}   j_{\pi, \shskip \psi} ( t(a) \varw_0 )    \widehat f (a)   \dx  a
	=     \sideset{ }{_{\BCx} }{\int}       e \lp {\mathrm{Tr}} ({\lambdaup} / {2 x} )  \rp \left| \lambdaup / 2 x \right|  \bfJ_{\frac 1 2 \mu,\shskip  \frac 1 2 m} \lp \lambdaup^2 / 16 x^2 \rp  f (x ) {  d x   }  ,
	\end{align}
	if $f$ is a Schwartz function on ${\mathbb {C}}$.

Relative Bessel functions for  ${\mathrm {GL
}_2 ({\mathbb {C}})$}
	Let $\pi$ be an infinite-dimensional irreducible unitary representation of $G = {\mathrm {GL}}_2 ({\mathbb {C}})$ with trivial central character. So if $\pi = \pi_{\mu, \shskip  m}$ then $m$ is even. Let $J = J_{\pi, \shskip \psi}$ and $I = I_{\pi, \shskip \psi}$ be the normalized Bessel and relative Bessel distributions defined as in \S \ref{sec: distributions}. Recall the formula \eqref{eq: I(f) = int J},
	\begin{align*}
	 I  (f) = \frac 1 {L (\pi, 1/2)} \int_{\BCx} J  \lp \rho_{l} (t(b)) f \rp \dx  b.
	\end{align*}
	Let $X = A N \varw_0 N$. For $f \in C_c^{\infty} (X)$,   since $ J  $ is represented by the Bessel function $j = j_{\pi, \shskip \psi} $ on $X$ (Corollary \ref{cor53}), it follows  that
	\begin{align}\label{6eq: I = int}
	I  (f) = \frac 1 {L (\pi, 1/2)} \int_{\BCx} \lp \int_{X}  f(t(b)g) j  (g) dg \rp \dx  b .
	\end{align}

	\begin{lem}\label{6lem: rel Bessel for split f}
		Let $f \in C_c^{\infty} (X)$ be of the form
		\begin{align}\label{6eq: f splits}
		f (t(a) z(c) n(x) \varw_0 n(y)) = f_1 (a) f_2 (c) f_3 (x) f_4 (y),
		\end{align}
		with $f_1,  f_2 \in  C_c^{\infty}  (\BCx)$ and $f_3, f_4 \in C_c^{\infty}  ({\mathbb {C}})$. Then
		\begin{equation}\label{6eq: double int for I}
		\begin{split}
		& \int_{\BCx}    \int_{G}  f(t(b)g) j  (g) dg \shskip   \dx  b \\
		 = \ & \int_{\BCx} f_1 (b) \dx  b \int_{\BCx} f_2 (c) \dx  c  \int_{{\mathbb {C}}}   f_4 (y ) \psi (y) d y \int_{\BCx} j  (t(a) \varw_0) \widehat f_3 (a) \dx  a,
		\end{split}
		\end{equation}
		where $ \widehat f_2 $ is the $\psi$-Fourier transform of $f_2$   defined as in  \eqref{def: Fourier}.
	\end{lem}

\begin{proof}
	Let $dg = \dx  a  \hskip 1 pt  \dx c \hskip 1 pt  d x \hskip 1 pt  d y$ be a Haar measure on $X$ for $g = t(a)  z(c) n(x) \varw_0 n(y)$. In view of \eqref{4eq: psi variant} and \eqref{6eq: f splits},
	the integral on the left hand side of \eqref{6eq: double int for I}   splits into the product
	\begin{align*}
	& \int  f_2 (c) \dx  c  \int   f_4 (y ) \psi (y) d y \int  \lp  \int  f_1 (ab) j  (t(a) \varw_0) \int f_3 (x) \psi (  a x) d x \shskip  \dx  a \rp \dx  b \\
	= \ & \int  f_2 (c) \dx  c  \int   f_4 (y ) \psi (y) d y \iint        f_1 (ab) j  (t(a) \varw_0) \widehat f_3 (a)    \dx  a \shskip   \dx  b.
	\end{align*}
	We claim that the last double integral converges absolutely. Hence we may change the order of integrations and the variable $b$ to $b/a$, getting
	\begin{align*}
	\iint        f_1 (ab) j  (t(a) \varw_0) \widehat f_3 (a)    \dx  a \shskip   \dx  b & = \int         j  (t(a) \varw_0) \widehat f_3 (a)  \int f_1 (ab) \dx  b \shskip   \dx  a \\
	& = \int f_1 (b  ) \dx  b \int    j  (t(a) \varw_0) \widehat f_3 (a)     \dx  a.
	\end{align*}
	We now show   the absolute  convergence. Choose $|{\mathrm{Re}\,} \mu | < \rho <  \frac 1 2$.  Lemma \ref{4lem: bounds for J} implies that $j  (t(a) \varw_0)$ may be bounded by $|a|^{1 - 2\rho} +   {|a|}^{\frac 1 2}$. We can find positive constants $A$ and $B$ such that $f_1 (a ) \lll \Upsilon_{A, B} (a)$, with $ \Upsilon_{A, B} (a)$ defined to be the characteristic function on the annulus $\left\{ a : A \leqslant |a| \leqslant B \right\}$. Hence
	\begin{align*}
	\int      \big|  f_1 (ab) j  (t(a) \varw_0) \widehat f_3(a)  \big|  \dx  a  \lll \int \Upsilon_{A/|b|, B/|b|} (a) \big|\widehat f_3 (a) \big| \big( |a|^{- 1- 2 \rho} + |a|^{- \frac 3 2} \big) d a.
	\end{align*}
	Since $\widehat f_3 (a)$ is rapidly decreasing when $|a|$ is large, it follows that the value of the integral above is rapidly decreasing when $|b|$ is small. When $|b|$ is large the integral is bounded by $  |b|^{2 \rho - 1} + |b|^{- \frac 1 2}$. It is then clear that integrating further with $\dx  b = d b / |b|^2$ will converge absolutely  at both $0$ and $\infty$.
\end{proof}

Combining \eqref{6eq: Fourier transform of j}, \eqref{6eq: I = int} and \eqref{6eq: double int for I}, it follows that if we define a function $i = i_{\pi, \shskip \psi}$ supported on $U$ such that
\begin{align}\label{6eq: defn of i}
i_{\pi, \shskip \psi} ( n(x)  \varw_0  ) =     e \lp {\mathrm{Tr}} ({\lambdaup} / {2 x} )  \rp \left| \lambdaup / 2 x \right|  \bfJ_{\frac 1 2 \mu,\shskip  \frac 1 2 m} \lp \lambdaup^2 / 16 x^2 \rp / {L (\pi, 1/2)},
\end{align}
and that $i_{\pi, \shskip \psi}$ is   right $  (\psi, N)$-equivariant and left $A$-invariant, namely,
\begin{align}\label{eq: equivariance of i}
i_{\pi, \shskip \psi} (t(a) z(c) n(x) \varw_0 n(y)) = \psi (y) i_{\pi, \shskip \psi} ( n(x)  \varw_0  ),
\end{align}
then
