\begin{align}\label{eq: O AN (g)}
O^{A, \shskip N}_{f, \shskip \psi} (g) = \int_A \int_N  f (a g  n) \psi (n) \dx a \hskip 1 pt d n.
\end{align}
It is proven in \cite{Jacquet-RTF} that the integral in \eqref{eq: O AN (g)}  converges absolutely for any $g \in U =  A (N \smallsetminus \{0\} ) \varw_0 N$. In view of Proposition \ref{prop81: local integ. of i} and \ref{prop82:regularity of I}, along with \eqref{eq: equivariance of i}, 



  for  $f \in C_c^{\infty} (G)$ we have
\begin{align}\label{eq: I = int O}
I_{\pi,\shskip \psi} (f) = \int_{ \BCx} O^{A, \shskip N}_{f, \shskip \psi} (n(x) \varw_0) i_{\pi,\shskip \psi} (n(x) \varw_0) d x.
\end{align}

\begin{proof}
	The proof is a simple comparison between the formulae \eqref{4eq: j = J, SL} and \eqref{6eq: defn of i}. To verify the equality,  it should be noted that by \cite[(4.7)]{Knapp} and \cite[\S 3]{Tate} we have $\epsilon (\pi, s, \psi_{\lambdaup}) = i^{|m|} \omega_{\pi} (\lambdaup) \|\lambdaup\|^{2s -1}$ if $\pi = \pi_{\mu, \shskip  m}$, and hence $\epsilon (\pi, 1/2, \psi_{\lambdaup}) = i^{|m|} = (-1)^{\frac 1 2 m}$ when $m$ is even so that $\omega_{\pi} (\lambdaup) = 1$. Note that $\epsilon (\pi, 1/2, \psi)$ is actually independent on $\psi$.
\end{proof}

We remark that $ \sigma = \Theta (\pi) = \Theta (\pi , \psi^D)$ according to the notation of the theta correspondence of Waldspurger \cite{Waldspurger-Shimura}. Unlike the real case (see \cite[Theorem 19.2]{BaruchMao-Real}),  here $\sigma$    is independent on the additive character $\psi^D$. 




Finally, we would like to prove an identity in the level of distributions. 
It is proven in \cite{Jacquet-RTF} that for each $f \in C_c^\infty (G)$ there exists $f' \in C_c^\infty (S)$ such that
\begin{equation}\label{eq: O AN = O NN}
O^{A, \shskip N}_{f, \shskip \psi} (n(z/4D) \varw_0) = O^{N, \shskip N}_{f', \shskip \psi^D} (\varw s(z)) \psi (-2D/z) {\textstyle \sqrt {\|z\|}}/ \gamma (z, \psi^D),
\end{equation}
for all $z \in \BCx$. See \eqref{eq: O NN (g)} and \eqref{eq: O AN (g)} for the definitions of these orbital integrals (the Haar measure in \eqref{eq: O NN (g)} however is now chosen with respect to $\psi$ rather than $\psi^D$).   By \eqref{eq: J = int O}, \eqref{eq: I = int O} and Theorem \ref{thm: main} we have the following theorem.
